<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_auth_message() { $code = isset( $_GET['sd_auth'] ) ? sanitize_key( wp_unslash( $_GET['sd_auth'] ) ) : ''; $messages = array( 'login-error' => array( 'error', __( 'We could not sign you in with those details.', 'social-discovery' ) ), 'registration-disabled' => array( 'error', __( 'Registration is currently disabled.', 'social-discovery' ) ), 'invalid-registration' => array( 'error', __( 'Please review the registration form and try again.', 'social-discovery' ) ), 'registration-error' => array( 'error', __( 'We could not create that account. Please try again.', 'social-discovery' ) ), 'password-sent' => array( 'success', __( 'If an account matches those details, a reset email has been sent.', 'social-discovery' ) ), 'password-error' => array( 'error', __( 'We could not process that password request.', 'social-discovery' ) ), 'reset-error' => array( 'error', __( 'That reset link is invalid or has expired.', 'social-discovery' ) ), 'reset-success' => array( 'success', __( 'Your password was updated. You can sign in now.', 'social-discovery' ) ), 'rate-limited' => array( 'error', __( 'Too many attempts. Please wait and try again later.', 'social-discovery' ) ) ); if ( isset( $messages[ $code ] ) ) { get_template_part( 'template-parts/auth/auth-message', null, array( 'type' => $messages[ $code ][0], 'message' => $messages[ $code ][1] ) ); } }
function sd_auth_assets() { if ( is_page_template( array( 'page-templates/login.php', 'page-templates/register.php', 'page-templates/forgot-password.php', 'page-templates/reset-password.php', 'page-templates/onboarding.php', 'page-templates/account-settings.php', 'page-templates/member-profile.php' ) ) ) { wp_enqueue_style( 'sd-authentication', SD_URI . '/assets/css/authentication.css', array( 'sd-style' ), SD_VERSION ); wp_enqueue_style( 'sd-member-profile', SD_URI . '/assets/css/member-profile.css', array( 'sd-authentication' ), SD_VERSION ); wp_enqueue_style( 'sd-onboarding', SD_URI . '/assets/css/onboarding.css', array( 'sd-authentication' ), SD_VERSION ); wp_enqueue_style( 'sd-auth-responsive', SD_URI . '/assets/css/auth-responsive.css', array( 'sd-authentication' ), SD_VERSION ); wp_enqueue_script( 'sd-authentication', SD_URI . '/assets/js/authentication.js', array(), SD_VERSION, true ); wp_enqueue_script( 'sd-profile', SD_URI . '/assets/js/profile.js', array(), SD_VERSION, true ); wp_enqueue_script( 'sd-onboarding', SD_URI . '/assets/js/onboarding.js', array(), SD_VERSION, true ); } }
add_action( 'wp_enqueue_scripts', 'sd_auth_assets' );
